const fan=(c,x,y,r,a)=>{c.save();c.translate(x,y);c.rotate(a);c.fillStyle='rgba(168,151,255,.32)';c.strokeStyle='#f2e5ff';c.lineWidth=1.2;c.beginPath();c.moveTo(0,0);c.arc(0,0,r,-2.75,-.40);c.closePath();c.fill();c.stroke();for(let j=0;j<8;j++){let t=-2.75+j*2.35/7;c.beginPath();c.moveTo(0,0);c.lineTo(r*Math.cos(t),r*Math.sin(t));c.stroke();}c.restore();};
