if(p.characterId==='glm'){for(let j=0;j<(p.ultimate?3:2);j++){c.globalAlpha=1-j*.2;glyph(c,-j*13,Math.sin(t*9+j)*3,19,t*.4+j*.12);}c.strokeStyle='#e4d2a2';c.beginPath();c.moveTo(-58,0);c.lineTo(-15,0);c.stroke();}
